        /// <summary>The citation of <paramref name="id"/> ("S7" or "[S7]"); null for unknown ids.</summary>
        public static I18nText? Get(string? id)
        {
            if (id is null || id.Trim().Length == 0) return null;
            var key = id.Trim().Trim('[', ']');
            return Entries.TryGetValue(key, out var t) ? t : null;
        }

        /// <summary>All ids in order (S1, S2 ...).</summary>
        public static IEnumerable<string> Ids => Entries.Keys;
